adcs_vec3_t vec;
double vnorm, w;

if ((predicted == NULL) || (measured == NULL) || (rotation_vector == NULL) || (angle == NULL)) {
    rotation_vector->x = 0.0;
    rotation_vector->y = 0.0;
    rotation_vector->z = 0.0;
    *angle = INFINITY;
    return ADCS_E_NULL;
}

if (adcs_quat_normalize(predicted, &qn_pred) != ADCS_OK) {
    rotation_vector->x = 0.0;
    rotation_vector->y = 0.0;
    rotation_vector->z = 0.0;
    *angle = INFINITY;
    return ADCS_E_DEGENERATE;
}
if (adcs_quat_normalize(measured, &qn_meas) != ADCS_OK) {
    rotation_vector->x = 0.0;
    rotation_vector->y = 0.0;
    rotation_vector->z = 0.0;
    *angle = INFINITY;
    return ADCS_E_DEGENERATE;
}

q_conj = adcs_quat_conjugate(&qn_pred);
q_rel = adcs_quat_multiply(&qn_meas, &q_conj);
if (q_rel.w < 0.0) {
    q_rel.w = -q_rel.w;
    q_rel.x = -q_rel.x;
    q_rel.y = -q_rel.y;
    q_rel.z = -q_rel.z;
}

w = ADCS_CLAMP(q_rel.w, 0.0, 1.0);
*angle = 2.0 * acos(w);

vec.x = q_rel.x;
vec.y = q_rel.y;
vec.z = q_rel.z;
vnorm = adcs_vec3_norm(&vec);

if (vnorm <= ADCS_EPS_NORM) {
    rotation_vector->x = 0.0;
    rotation_vector->y = 0.0;
    rotation_vector->z = 0.0;
} else {
    rotation_vector->x = (*angle) * q_rel.x / vnorm;
    rotation_vector->y = (*angle) * q_rel.y / vnorm;
    rotation_vector->z = (*angle) * q_rel.z / vnorm;
}

return ADCS_OK;

